/**
 * TASK: Observe a plain (non-Swing) model with a PropertyChangeListener.
 *
 * HeaterModel below fires property change events through a
 * PropertyChangeSupport. In the ThermostatObserverPanel constructor,
 * register ONE listener on the model that reacts to both properties:
 *
 *   property "target" -- put the new value plus " C" in the label named
 *                        "target", so 22 becomes "22 C"
 *   property "on"     -- put "on" or "off" in the label named "power",
 *                        based on the new boolean value
 *
 * Every event you receive also adds 1 to the change counter reported by
 * changeCount().
 *
 * EDGE CASE: PropertyChangeSupport does NOT fire when the old and new value
 * are equal, so setting the target to the value it already has must leave
 * changeCount() alone -- you get that behaviour for free by counting only
 * the events that actually arrive.
 *
 * Use evt.getPropertyName() to tell the two properties apart and
 * evt.getNewValue() to read the new value.
 */
import java.beans.PropertyChangeListener;
import java.beans.PropertyChangeSupport;
import javax.swing.JLabel;
import javax.swing.JPanel;

class HeaterModel {

    private final PropertyChangeSupport support = new PropertyChangeSupport(this);
    private int target = 20;
    private boolean on = false;

    public void addPropertyChangeListener(PropertyChangeListener listener) {
        support.addPropertyChangeListener(listener);
    }

    public int getTarget() {
        return target;
    }

    public void setTarget(int newTarget) {
        int old = target;
        target = newTarget;
        support.firePropertyChange("target", old, newTarget);
    }

    public boolean isOn() {
        return on;
    }

    public void setOn(boolean newOn) {
        boolean old = on;
        on = newOn;
        support.firePropertyChange("on", old, newOn);
    }
}

public class ThermostatObserverPanel extends JPanel {

    private final HeaterModel model = new HeaterModel();
    private final JLabel target = new JLabel("20 C");
    private final JLabel power = new JLabel("off");
    private int changes = 0;

    public ThermostatObserverPanel() {
        target.setName("target");
        power.setName("power");
        add(target);
        add(power);
