public class ThermostatObserverPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        if (c instanceof javax.swing.text.JTextComponent) {
            return ((javax.swing.text.JTextComponent) c).getText();
        }
        return "(missing)";
    }

    public static void main(String[] args) {
        try {
            ThermostatObserverPanel panel = new ThermostatObserverPanel();
            HeaterModel model = panel.getModel();
            java.awt.Component targetLabel = find(panel, "target");
            java.awt.Component powerLabel = find(panel, "power");

            check("labels start at 20 C / off",
                    "20 C off", textOf(targetLabel) + " " + textOf(powerLabel));
            check("no changes yet", 0, panel.changeCount());

            model.setTarget(22);
            check("target label after setTarget(22)", "22 C", textOf(targetLabel));
            check("one change counted", 1, panel.changeCount());

            model.setTarget(22);
            check("setting the same target fires nothing", 1, panel.changeCount());

            model.setOn(true);
            check("power label after setOn(true)", "on", textOf(powerLabel));
            check("target label untouched by the on event", "22 C", textOf(targetLabel));
            check("two changes counted", 2, panel.changeCount());

            model.setOn(false);
            check("power label after setOn(false)", "off", textOf(powerLabel));

            model.setTarget(18);
            check("target label after setTarget(18)", "18 C", textOf(targetLabel));
            check("four changes counted", 4, panel.changeCount());
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected problem -- " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

