import java.beans.PropertyChangeListener;
import java.beans.PropertyChangeSupport;
import javax.swing.JLabel;
import javax.swing.JPanel;

class HeaterModel {

    private final PropertyChangeSupport support = new PropertyChangeSupport(this);
    private int target = 20;
    private boolean on = false;

    public void addPropertyChangeListener(PropertyChangeListener listener) {
        support.addPropertyChangeListener(listener);
    }

    public int getTarget() {
        return target;
    }

    public void setTarget(int newTarget) {
        int old = target;
        target = newTarget;
        support.firePropertyChange("target", old, newTarget);
    }

    public boolean isOn() {
        return on;
    }

    public void setOn(boolean newOn) {
        boolean old = on;
        on = newOn;
        support.firePropertyChange("on", old, newOn);
    }
}

public class ThermostatObserverPanel extends JPanel {

    private final HeaterModel model = new HeaterModel();
    private final JLabel target = new JLabel("20 C");
    private final JLabel power = new JLabel("off");
    private int changes = 0;

    public ThermostatObserverPanel() {
        target.setName("target");
        power.setName("power");
        add(target);
        add(power);
        model.addPropertyChangeListener(evt -> {
            changes++;
            if ("target".equals(evt.getPropertyName())) {
                target.setText(evt.getNewValue() + " C");
            } else if ("on".equals(evt.getPropertyName())) {
                boolean running = (Boolean) evt.getNewValue();
                power.setText(running ? "on" : "off");
            }
        });
    }

    public HeaterModel getModel() {
        return model;
    }

    public int changeCount() {
        return changes;
    }
}
